### 2-1. `useModel`: when you only need local data

```tsx
import { useModel } from "@firsttx/local-first";
import { CartModel } from "./models/cart";

export function CartSidebar() {
  const { data: cart, patch, history, error, status } = useModel(CartModel);

  if (status === "loading") {
    return <div className="text-xs text-muted-foreground">Loading...</div>;
  }

  if (status === "error") {
    return (
      <div className="text-xs text-destructive">
        Failed to load cart: {error?.getUserMessage?.() ?? String(error)}
      </div>
    );
  }

  if (!cart) {
    return <div className="text-xs text-muted-foreground">No cart yet.</div>;
  }

  return (
    <ul className="space-y-1 text-sm">
      {cart.items.map((item) => (
        <li key={item.id} className="flex items-center justify-between">
          <span>{item.name}</span>
          <span className="text-muted-foreground">x {item.qty}</span>
        </li>
      ))}

      {history && (
        <p className="mt-2 text-[11px] text-muted-foreground">
          Last updated {Math.round(history.age / 1000)}s ago
          {history.isStale && " · stale"}
        </p>
      )}
    </ul>
  );
}
```

- `useModel` synchronously returns the model's current **in-memory external-store snapshot**.
- IndexedDB loading happens asynchronously in the model lifecycle and updates that snapshot when it completes. The hook itself does not trigger server synchronization.

useModel(model) return value
- `data` (type: `T | null`, optional) — Current model data. `null` if there is no value yet.
- `status` (type: `'loading' | 'success' | 'error'`, optional) — Current loading status. Use this to distinguish between loading, success, and error states.
- `patch` (type: `(mutator: (draft: T) => void) => Promise<void>`, optional) — Function to update local data. It validates with Zod, persists to IndexedDB, and emits broadcast/DevTools events.
- `history` (type: `{ updatedAt: number | null; age: number; isStale: boolean }`, option

### 2-2. `useSyncedModel`: when you want server sync as well

```tsx
import { useSyncedModel } from "@firsttx/local-first";
import { CartModel } from "./models/cart";

async function fetchCart(current: unknown) {
  // current contains the currently cached value (or null).
  const res = await fetch("/api/cart");
  if (!res.ok) throw new Error("Failed to fetch cart");
  return res.json();
}

export function CartPage() {
  const {
    data: cart,
    isSyncing,
    error,
    history,
    patch,
    sync,
  } = useSyncedModel(CartModel, fetchCart, {
    syncOnMount: "stale", // "always" | "stale" | "never"
  });

  if (error) {
    return (
      <div className="text-sm text-destructive">
        Failed to sync: {error.getUserMessage?.() ?? error.message}
      </div>
    );
  }

  if (!cart) {
    return <div>Loading cart…</div>;
  }

  return (
    <div className="space-y-4">
      {cart.items.map((item) => (
        <div key={item.id} className="flex items-center justify-between">
          <span>{item.name}</span>
          <span className="text-sm text-muted-foreground">x {item.qty}</span>
        </div>
      ))}

      <div className="flex items-center gap-3 text-xs text-muted-foreground">
        {isSyncing && <span>Syncing latest data…</span>}
        {history && (
          <span>
            Last updated {Math.round(history.age / 1000)}s ago
            {history.isStale && " (stale)"}
          </span>
        )}
        <button
          type="button"
          onClick={() => sync("manual")}
          className="rounded-full border border-border px-2 py-0.5 text-[11px]"
        >
          Refresh
        </button>
      </div>
    </div>
  );
}
```

useSyncedModel(model, fetcher, options)
- `fetcher` (type: `(current: T | null) => Promise<T>`, required) — <>
Function that fetches the latest data from the server. Receives the current cached value (or `null`) as its first argument. On success, Local-First calls `replace`
on the model with the new data.

),
}

,
{
- `options.syncOnMount` (default: `"always"`, optional) — <>
Strategy for automatic sync when the component mounts.

-
`"always"`: always sync once on mount, regardless of TTL (default)

-
`"stale"`: sync only when `history.isStale` is `true`

-
`"never"`: no automatic sync; only sync when you call `sync()` manually.

),
},
{
- `options.retry` (type: `RetryConfig | null`, default: `null`, optional) — <>
Retry strategy when the sync request fails. Uses the same shape as `@firsttx/tx`'s retry config (`maxAttempts`, `delayMs`, `backoff`). If omitted, no retry is performed.

),
},
{
- `options.onSuccess` (type: `(data: T) => void`, optional) — <>Callback invoked when sync succeeds. ,
},
{
- `options.onError` (type: `(error: FirstTxError) => void`, optional) — <>
Callback invoked when an error occurs during sync. DevTools also records a `sync.error` event.

),
},
]}
/>

useSyncedModel(model, fetcher, options) return value
- `data` (type: `T | null`, optional) — Current model data. `null` if there is no value yet.
- `status` (type: `'loading' | 'success' | 'error'`, optional) — Current loading status from the underlying model. Use this to distinguish between loading, success, and error states.
- `history` (type: `{ updatedAt: number | null; age: number; isStale: boolean }`, optional) — Last update time and freshness information based on TTL.
- `error` (type: `FirstTxError | null`, optional) — Error from the last sync attempt. Takes precedence over model-level errors.
- `isSyncing` (type: `boolean`, optional) — Whether a server sync is currently in progress.
- `patch` (type: `typeof model.patch`, optional) — Direct reference to the model's `patch` method. Use this for local optimistic updates.
- `sync` (type: `(trigger?: 'mount' | 'manual') => Promise<void>`, optional) — Function to manually trigger sync. Internally it deduplicates concurrent calls and records `sync.start`/`sync.success`/`sync.error` events in DevTools.

Avoiding duplicate sync within one hook instance

## 4. Suspense integration

Local-First integrates nicely with React Suspense.
The easiest way is to use the `useSuspenseSyncedModel` hook.

```tsx
import { Suspense } from "react";
import { useSuspenseSyncedModel } from "@firsttx/local-first";
import { CartModel } from "./models/cart";

async function fetchCart() {
  const res = await fetch("/api/cart");
  if (!res.ok) throw new Error("Failed to fetch cart");
  return res.json();
}

function CartInner() {
  const cart = useSuspenseSyncedModel(CartModel, fetchCart);

  return (
    <ul className="space-y-2 text-sm">
      {cart.items.map((item) => (
        <li key={item.id}>{item.name}</li>
      ))}
    </ul>
  );
}

export function SuspenseCart() {
  return (
    <Suspense fallback={<div>Loading cart…</div>}>
      <CartInner />
    </Suspense>
  );
}
```

- When there is no data and no error yet, the hook calls `model.getSyncPromise(fetcher)` and throws the returned Promise so the nearest Suspense boundary can render its fallback.
- If the cache already has data, it simply returns and does not go through Suspense.
- If there is an error, it is thrown so that your ErrorBoundary can handle it.

`getSyncPromise()` only returns a Promise; it does not throw by itself. Prefer `useSuspenseSyncedModel` unless you also implement the cache/error checks and Promise-throwing boundary that the hook owns.

