    optimistic: (input) => {
      CartModel.patch((draft) => {
        draft.items.push(input);
      });

      // Whatever you return here becomes a snapshot passed to rollback / onSuccess, etc.
      // In this example we don't need it, so we just return void (snapshot type: void).
    },

